#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <float.h>

static const float *F;
int main(int c,char**v){
 int fd=open(v[1],O_RDONLY); struct stat stt; fstat(fd,&stt);
 long sz=stt.st_size;
 char*m=mmap(0,sz,PROT_READ,MAP_PRIVATE,fd,0);
 F=(float*)m;
 long nf=sz/4;
 double mn=FLT_MAX,mx=-FLT_MAX; long nnan=0;
 double gsum=0,gsum2=0;
 for(long i=0;i<nf;i++){
   double x=F[i];
   if(isnan(x)||isinf(x)){nnan++;continue;}
   if(x<mn)mn=x; if(x>mx)mx=x;
   gsum+=x; gsum2+=x*x;
 }
 printf("nan/inf=%ld min=%.6f max=%.6f mean=%.6f std=%.6f\n",nnan,mn,mx,gsum/nf,sqrt(gsum2/nf-gsum/nf*gsum/nf));
 for(int i=0;i<32;i++) printf("%.6f ",F[i]); printf("\n");
 // row-norm scan in chunks of 1M floats
 printf("chunk(mean norm, std norm, #norm<2, #norm>50):\n");
 for(long b=0;b<nf;b+=1000000){
   long e=b+1000000<nf?b+1000000:nf;
   double s=0,s2=0; long lo=0,hi=0,n=0;
   for(long r=b;r+768<=e;r+=768){
     double q=0; for(int i=0;i<768;i++){double d=F[r+i];q+=d*d;}
     q=sqrt(q); s+=q; s2+=q*q; n++;
     if(q<2)lo++; if(q>50)hi++;
   }
   printf("  [%ld..%ld] mean=%.4f std=%.4f lo=%ld hi=%ld n=%ld\n",b,e,s/n,sqrt(s2/n-s/n*s/n),lo,hi,n);
 }
 // gamma-like 768 windows across whole file
 long hits=0;
 for(long o=0;o+768<=nf;o++){
   double m=0; for(int i=0;i<768;i++)m+=F[o+i]; m/=768;
   if(m>0.95&&m<1.05){
     double vv=0; for(int i=0;i<768;i++){double d=F[o+i]-m;vv+=d*d;} vv/=768;
     if(sqrt(vv)<0.25&&hits<40){printf("gamma? off=%ld mean=%.4f std=%.4f\n",o,m,sqrt(vv));hits++;}
   }
 }
 printf("gamma-like hits=%ld\n",hits);
 return 0;
}

