#include <stdio.h>
#include <stdlib.h>
#include <math.h>
int main(int c,char**v){
 static float*F;
 FILE*f=fopen(v[1],"rb");
 fseek(f,0,SEEK_END); long n=ftell(f); rewind(f);
 F=(float*)malloc(n); if(fread(F,1,n,f)!=(size_t)n)return 1;
 fclose(f);
 long nf=n/4;
 double s=0,s2=0; float mn=1e9,mx=-1e9;
 for(long i=0;i<nf;i++){double x=F[i];s+=x;s2+=x*x;if(x<mn)mn=x;if(x>mx)mx=x;}
 printf("global n=%ld mean=%.5f std=%.5f mn=%f mx=%f\n",nf,s/nf,sqrt(s2/nf-s*s/(nf*nf)),mn,mx);
 // top windows by |mean|
 struct W{long o;float m;};
 long nw=nf/768;
 static struct W ww[200000];
 for(long i=0;i<nw;i++){long o=i*768;float s=0;for(int k=0;k<768;k++)s+=F[o+k];ww[i].m=s/768;ww[i].o=o;}
 for(long a=0;a<nw;a++)for(long b=a+1;b<nw;b++)
   if((ww[b].m>0?ww[b].m:-ww[b].m)>(ww[a].m>0?ww[a].m:-ww[a].m)){struct W t=ww[a];ww[a]=ww[b];ww[b]=t;}
 // that's O(n^2) - too slow; use partial instead
 printf("top by naive sort skipped; using threshold scan\n");
 for(long o=0;o+768<=nf;o+=768){
   float s=0;for(int k=0;k<768;k++)s+=F[o+k];s/=768;
   if(s>0.3)printf("WIN %ld mean=%.4f\n",o,s);
 }
 return 0;}
EOF
